// append_records_q6.js — extend the published K1177 frontier records.jsonl (112
// records after the q=7 closure band extension) with the two q=6 band-extension
// records: (4,30,6) and (4,31,6) def-mode UNSAT, generated by the genfast3
// chord-pair abstract-circle census (md5 12c2bd9cb3b24887fc3896f7ea9bcadf, core
// sat2.js md5 282ae832efa0080127c6c153e65e1c3c), whose CNF at the published
// control (4,29,6) is byte-identical (md5 95816b6c04c14de5f0256ca871dfcc97) to
// the sat2.js record s4x29q6_def. Fail-closed: refuses on any duplicate tag, on
// an input that is not exactly 112 records, or on any mismatch against the
// published live artifacts (gen meta JSONs and kissat solve logs in output/q6ext/).
'use strict';
const fs = require('fs');
const [, , inPath, outPath, liveDir] = process.argv;
const GEN = 'genfast3.js-md5-12c2bd9cb3b24887fc3896f7ea9bcadf-core-sat2.js-md5-282ae832efa0080127c6c153e65e1c3c';
// calibration pin: byte-identity of the genfast3 CNF instance with the published sat2.js record
const CALIB = { m: 29, curves: 748, vars: 16688, clauses: 58033, cnf_md5: '95816b6c04c14de5f0256ca871dfcc97' };
// (m, vars, clauses, curves, cnf_md5, gen_sec, conflicts, sec, ts)
const rows = [
  [30, 17967, 62482, 807, '7ebcea335bf52821c9abbdf170d5970a', 0.2, 3091289, 202.54, '2026-11-21T02:24:30Z'],
  [31, 19246, 66931, 866, '7c6acc085ddf1820b4742bd2c47286a6', 0.1, 3492659, 237.06, '2026-11-21T02:28:20Z'],
];
const lines = fs.readFileSync(inPath, 'utf8').split('\n').filter(l => l.trim());
if (lines.length !== 112) { console.error('refuse: expected exactly 112 input records, got ' + lines.length); process.exit(1); }
const recs = lines.map(l => JSON.parse(l));
const tags = new Set(recs.map(r => r.tag));
for (const [m] of rows) {
  const tag = 's4x' + m + 'q6_def';
  if (tags.has(tag)) { console.error('refuse: ' + tag + ' already present'); process.exit(1); }
}
// parent-of-band schema check: the published (4,29,6) UNSAT record must match the calibration pin
const p29 = recs.find(r => r.tag === 's4x' + CALIB.m + 'q6_def');
if (!p29 || p29.kissat.result !== 'UNSATISFIABLE' || p29.kissat.rc !== 20 ||
    p29.vars !== CALIB.vars || p29.clauses !== CALIB.clauses || p29.curves !== CALIB.curves ||
    p29.cnf_md5 !== CALIB.cnf_md5)
  { console.error('refuse: s4x29q6_def parent record does not match the calibration pin'); process.exit(1); }
// verify every appended value against the published live artifacts
for (const [m, vars, clauses, curves, , , conflicts, sec] of rows) {
  const meta = JSON.parse(fs.readFileSync(liveDir + '/gen_4x' + m + 'q6_def.json', 'utf8'));
  if (meta.w !== 4 || meta.m !== m || meta.q !== 6 || meta.mode !== 'deficient' ||
      (meta.lex || []).length !== 0 || meta.vars !== vars || meta.clauses !== clauses ||
      meta.curves !== curves)
    { console.error('refuse: gen meta mismatch m=' + m); process.exit(1); }
  const log = fs.readFileSync(liveDir + '/solve_4x' + m + 'q6_def.txt', 'utf8');
  const confOk = new RegExp('c conflicts:[ ]+' + conflicts + '[ ]').test(log);
  const verOk = log.indexOf('s UNSATISFIABLE') >= 0;
  const exitOk = /c exit 20\s*$/.test(log);
  const timeOk = log.indexOf(sec + ' seconds') >= 0;
  if (!(confOk && verOk && exitOk && timeOk))
    { console.error('refuse: solve log mismatch m=' + m); process.exit(1); }
}
// append (field order and types byte-match the published schema)
const out = lines.slice();
for (const [m, vars, clauses, curves, md5, gen_sec, conflicts, sec, ts] of rows) {
  const rec = {
    w: 4, m: m, q: 6, mode: 'deficient', rowY: null, generator: GEN,
    vars: vars, clauses: clauses, curves: curves, cnf_md5: md5,
    gen_sec: gen_sec, gen_extra: '',
    kissat: { result: 'UNSATISFIABLE', rc: 20, conflicts: conflicts, sec_cap: 280, sec: sec },
    ts: ts, witness: null, tag: 's4x' + m + 'q6_def', cnf_deleted: true,
  };
  out.push(JSON.stringify(rec));
}
fs.writeFileSync(outPath, out.join('\n') + '\n');
console.log(JSON.stringify({ input_records: lines.length, output_records: out.length, appended: rows.length }));
